/** 🧪️ Procedural owned relational laws inspected with independent SQLite. */
import {test,expect} from "bun:test";
import {Database} from "bun:sqlite";
import {generation2dSnapshotToSqliteDatabase,generation2dSnapshotFromSqliteDatabase,GENERATION2D_SQLITE_SCHEMA} from "../../🪶️sqlite/🟦️.ts";
